p {
    color: red;
}
.card {
    padding: 20px;
}
#title {
    color: blue;
}
.card p {
    color: gray;
}
.card > p {
    color: gray;
}

* {
    box-sizing: border-box;
}

.card {
    width: 300px;
    padding: 20px;
    border: 5px solid black;
    box-sizing: border-box;
}

.container {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 20px;
}

font-size: clamp(1rem, 2vw, 3rem);

img {
    max-width: 100%;
    height: auto;
}

button {
    transition: background 0.3s ease;
}
button:hover {
    background: blue;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}
.box {
    animation: fadeIn 1s ease;
}
